#' Generate Data for a Spearman Rank Correlation
#'
#' Creates two variables with a targeted Spearman's rho, EXACT medians,
#' and (by default) a monotonic-but-nonlinear relationship — the
#' situation Spearman's correlation exists for. Runs R's canonical
#' \code{cor.test(method = "spearman")}, the nonparametric counterpart
#' of Pearson's r as generated by [cor_gen()].
#'
#' Sample Spearman correlations are discrete (they are Pearson
#' correlations on ranks), so rho is targeted to 2 decimal places by
#' iterative refinement rather than hit exactly; the achieved value is
#' reported. Medians are exact. With \code{relationship = "monotonic"}
#' (default), Y follows an exponential transform of X's ranks — visibly
#' curved but strictly monotone, so Spearman detects what Pearson
#' understates; \code{"linear"} gives a straight-line relationship
#' instead.
#'
#' @param n Number of pairs (minimum 10)
#' @param rho Target Spearman correlation, strictly between -1 and 1
#'   (matched to 2 decimals)
#' @param medians Numeric vector of length 2: target medians for X and
#'   Y (hit exactly)
#' @param spreads Numeric vector of length 2: SD-like scales for X and
#'   Y (approximate)
#' @param relationship \code{"monotonic"} (default; curved) or
#'   \code{"linear"}
#' @param shape Distribution shape for X, as in [dist_gen()]
#'   (default = \code{"right_skew"})
#' @param severity Shape severity (default = \code{"moderate"})
#' @param scale_min,scale_max Optional bounds, each either a single
#'   value (applied to both variables) or a vector of length 2
#' @param var_names Character vector of length 2 (default
#'   \code{c("X", "Y")})
#' @param decimals Number of decimal places (default = 0)
#' @param seed Integer seed for reproducibility (default = \code{NULL})
#' @param export_csv Either \code{FALSE} (default; nothing is written),
#'   \code{TRUE} (write a CSV with an auto-generated name to the current
#'   working directory), or a file path giving the CSV destination
#' @param run_analysis Logical; run the Spearman test automatically?
#'   (default = \code{TRUE})
#'
#' @return (Invisibly) a list with:
#'   \item{data}{Data frame with the two variables}
#'   \item{variable_stats}{Exact median and IQR per variable}
#'   \item{rho_achieved}{The achieved sample Spearman correlation}
#'   \item{r_squared}{\code{rho_achieved^2}, the proportion of rank
#'     variance explained}
#'   \item{test_results}{The \code{cor.test(method = "spearman")}
#'     result}
#'   \item{iterations}{Refinement iterations}
#'
#' @seealso [cor_gen()] for Pearson correlation with exact r,
#'   [anscombe_gen()] for same-statistics-different-shapes lessons
#'
#' @examples
#' # Satisfaction (1-100) vs spending: monotonic, right-skewed
#' result <- spearman_gen(
#'   n = 25, rho = 0.46,
#'   medians = c(75, 60), spreads = c(12, 30),
#'   var_names = c("Satisfaction", "Spending"),
#'   scale_min = c(1, 0), scale_max = c(100, 500), seed = 42
#' )
#' result$rho_achieved
#' result$test_results
#'
#' @concept Spearman correlation
#' @concept nonparametric
#' @concept monotonic relationship
#'
#' @export
spearman_gen <- function(n,
                         rho,
                         medians,
                         spreads,
                         relationship = "monotonic",
                         shape        = "right_skew",
                         severity     = "moderate",
                         scale_min    = NULL,
                         scale_max    = NULL,
                         var_names    = c("X", "Y"),
                         decimals     = 0,
                         seed         = NULL,
                         export_csv   = FALSE,
                         run_analysis = TRUE) {

  if (!is.numeric(n) || n < 10 || n != round(n))
    stop("'n' must be an integer >= 10")
  if (!is.numeric(rho) || length(rho) != 1 || rho <= -1 || rho >= 1)
    stop("'rho' must be strictly between -1 and 1")
  if (length(medians) != 2) stop("'medians' must have length 2")
  if (length(spreads) != 2 || any(spreads <= 0))
    stop("'spreads' must be two positive values")
  if (!relationship %in% c("monotonic", "linear"))
    stop("'relationship' must be 'monotonic' or 'linear'")
  if (length(var_names) != 2 || var_names[1] == var_names[2])
    stop("'var_names' must be two distinct names")
  expand2 <- function(b) if (is.null(b) || length(b) == 2) b else rep(b, 2)
  scale_min <- expand2(scale_min)
  scale_max <- expand2(scale_max)
  npar_validate_common(spreads[1], shape, severity, scale_min[1],
                       scale_max[1], decimals)
  npar_validate_median(medians[1], n, decimals, scale_min[1], scale_max[1],
                       what = "median (X)")
  npar_validate_median(medians[2], n, decimals, scale_min[2], scale_max[2],
                       what = "median (Y)")

  if (!is.null(seed)) set.seed(seed)
  draw_fun <- dist_shape_params(shape, severity)$draw
  target_2dp <- round(rho, 2)
  max_iter <- 100000

  finish <- function(v, j) {
    v <- v * spreads[j]
    v <- v - stats::median(v) + medians[j]
    v <- round(v, decimals)
    if (!is.null(scale_min)) v <- pmax(v, scale_min[j])
    if (!is.null(scale_max)) v <- pmin(v, scale_max[j])
    v
  }

  for (iter in seq_len(max_iter)) {
    zx <- as.vector(scale(draw_fun(n)))
    signal <- if (relationship == "monotonic") {
      as.vector(scale(exp(zx)))         # monotone in x, visibly curved
    } else {
      zx
    }
    zy <- rho * signal + sqrt(1 - rho^2) * as.vector(scale(stats::rnorm(n)))
    x <- finish(zx, 1)
    y <- finish(as.vector(scale(zy)), 2)

    ok_medians <-
      round(stats::median(x), decimals + 2) ==
        round(medians[1], decimals + 2) &&
      round(stats::median(y), decimals + 2) ==
        round(medians[2], decimals + 2)
    if (ok_medians && stats::sd(x) > 0 && stats::sd(y) > 0) {
      rho_ach <- suppressWarnings(
        stats::cor(x, y, method = "spearman"))
      if (round(rho_ach, 2) == target_2dp) break
    }
    if (iter >= max_iter) {
      warning("Maximum iterations reached; achieved rho may not match ",
              "the target to 2 decimals")
      break
    }
  }

  data_out <- data.frame(x, y, stringsAsFactors = FALSE)
  colnames(data_out) <- var_names

  variable_stats <- data.frame(
    Variable = var_names,
    Median   = c(stats::median(x), stats::median(y)),
    IQR      = c(stats::IQR(x), stats::IQR(y)),
    stringsAsFactors = FALSE
  )
  rho_achieved <- suppressWarnings(
    stats::cor(x, y, method = "spearman"))

  test_results <- NULL
  if (run_analysis) {
    test_results <- suppressWarnings(
      stats::cor.test(x, y, method = "spearman"))
  }

  dgen_export(data_out, export_csv,
              paste0(var_names[1], "_", var_names[2],
                     "_spearman_dgen.csv"))

  message(sprintf("Spearman data: n = %d, target rho = %.2f, achieved rho = %.3f",
                  n, rho, rho_achieved))
  if (run_analysis) {
    message(sprintf("cor.test (spearman): rho = %.3f, p = %s | R^2 = %.3f",
                    as.numeric(test_results$estimate),
                    format.pval(test_results$p.value, digits = 3,
                                eps = 0.001),
                    rho_achieved^2))
  }

  result <- list(
    data           = data_out,
    variable_stats = variable_stats,
    rho_achieved   = rho_achieved,
    r_squared      = rho_achieved^2,
    iterations     = iter
  )
  if (run_analysis) result$test_results <- test_results
  invisible(result)
}
